-- Lesson: absolute-entropy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0d591d05f40e52', 'absolute-entropy', 'Absolute entropy and entropy change', 'Use the third law and tabulated standard molar entropies to calculate ΔS° for a reaction, and check the result against a sign prediction.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_979d0e0e3a5b12', 'les_0d591d05f40e52', 1, 'State the third law: a perfect crystal at 0 K has S = 0, so absolute entropies can be tabulated.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0481638155bacb', 'les_0d591d05f40e52', 2, 'Calculate ΔS° = ΣnS°(products) − ΣnS°(reactants).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_177141dcb57317', 'les_0d591d05f40e52', 3, 'Check calculated values against qualitative predictions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_979d0e0e3a5b12', 'les_0d591d05f40e52', 'learn', 1, 'definition', '{"term":"The third law","body":"A perfect crystal at absolute zero has only one microstate, so $S = k\\ln 1 = 0$. Measuring heat absorbed while warming from 0 K gives each substance an absolute standard molar entropy $S^\\circ$ (J/(mol·K)). Unlike $\\Delta H_f^\\circ$, elements do not have $S^\\circ = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0481638155bacb', 'les_0d591d05f40e52', 'learn', 2, 'definition', '{"term":"Reaction entropy","body":"$\\Delta S^\\circ_{\\text{rxn}} = \\sum nS^\\circ(\\text{products}) - \\sum nS^\\circ(\\text{reactants})$, using the coefficients $n$ from the balanced equation. Gases have large $S^\\circ$ (130–250), liquids moderate, solids small."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_177141dcb57317', 'les_0d591d05f40e52', 'learn', 3, 'worked_example', '{"title":"ΔS° for N₂(g) + 3H₂(g) → 2NH₃(g)","steps":[{"latex":"S^\\circ:\\ \\text{NH}_3\\ 192.5,\\ \\text{N}_2\\ 191.6,\\ \\text{H}_2\\ 130.7","explanation":"J/(mol·K)"},{"latex":"\\text{products: } 2(192.5) = 385.0","explanation":""},{"latex":"\\text{reactants: } 191.6 + 3(130.7) = 583.7","explanation":""},{"latex":"\\Delta S^\\circ = -198.7\\ \\text{J/K}","explanation":"Negative, as predicted from 4 → 2 mol gas."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_378f57be6747f6', 'les_0d591d05f40e52', 'learn', 4, 'callout', '{"tone":"warning","title":"Common mistakes","body":"Multiply by coefficients, include elements (their S° is not zero) and keep units straight: ΔS° comes out in J/K while ΔH° is in kJ. Convert before combining them in ΔG."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e0be01605e28f0', 'les_0d591d05f40e52', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers use tabulated entropies to find the maximum efficiency of engines and the conditions that make industrial reactions such as ammonia synthesis worthwhile."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_979d0e0e3a5b12', 'les_0d591d05f40e52', 1, 'practice', 'numeric', 2, 'Find ΔS° for CaCO₃(s) → CaO(s) + CO₂(g). S° values: CaCO₃ 92.9, CaO 38.1, CO₂ 213.8 J/(mol·K).', '{"answer":159,"tolerance":0.2,"unit":"J/K"}', '["Products minus reactants."]', '$38.1 + 213.8 - 92.9 = 159.0$ J/K.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0481638155bacb', 'les_0d591d05f40e52', 2, 'practice', 'numeric', 3, 'Find ΔS° for 2H₂(g) + O₂(g) → 2H₂O(l). S°: H₂ 130.7, O₂ 205.2, H₂O(l) 69.9 J/(mol·K).', '{"answer":-326.8,"tolerance":0.2,"unit":"J/K"}', '["Remember the coefficients of 2."]', '$2(69.9) - [2(130.7) + 205.2] = -326.8$ J/K.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_177141dcb57317', 'les_0d591d05f40e52', 3, 'practice', 'multiple_choice', 2, 'According to the third law, S = 0 for…', '{"choices":["every element at 298 K","a perfect crystal at 0 K","any gas at STP","water at its freezing point"],"answer":1}', '[]', 'Only one microstate.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_378f57be6747f6', 'les_0d591d05f40e52', 4, 'practice', 'multiple_choice', 2, 'Standard molar entropy of an element at 298 K is…', '{"choices":["zero by definition","positive","negative","undefined"],"answer":1}', '["Contrast with ΔH°f."]', 'Elements have positive absolute entropies.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e0be01605e28f0', 'les_0d591d05f40e52', 5, 'review', 'multiple_choice', 3, 'A calculated ΔS° of +150 J/K would be surprising for…', '{"choices":["C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l)","2NH₃(g) → N₂(g) + 3H₂(g)","NH₄Cl(s) → NH₃(g) + HCl(g)","PCl₅(g) → PCl₃(g) + Cl₂(g)"],"answer":0}', '["Count moles of gas on each side."]', '6 → 3 mol gas and a liquid formed: ΔS° should be negative.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0d591d05f40e52', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0d591d05f40e52', (SELECT id FROM formulas WHERE slug = 'free-energy'), 1);

-- Lesson: acid-strength-structure
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_53867f61064c3a', 'acid-strength-structure', 'Molecular structure of acids and bases', 'Explain acid strength from structure: bond strength and size for binary acids, electronegativity and oxygen count for oxyacids, and inductive effects in organic acids.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ec04aace244aed', 'les_53867f61064c3a', 1, 'Rank binary acids using bond strength down a group and electronegativity across a period.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69c0b4c7b3e15d', 'les_53867f61064c3a', 2, 'Rank oxyacids by central-atom electronegativity and number of oxygens.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fd492e7d9dbd97', 'les_53867f61064c3a', 3, 'Explain strength through the stability of the conjugate base.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec04aace244aed', 'les_53867f61064c3a', 'learn', 1, 'definition', '{"term":"The guiding idea","body":"An acid is stronger when its conjugate base is more stable, that is, when the negative charge left behind is spread out or pulled toward electronegative atoms. A stronger acid has a larger $K_a$ and a smaller p$K_a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69c0b4c7b3e15d', 'les_53867f61064c3a', 'learn', 2, 'definition', '{"term":"Binary acids, H–X","body":"Down a group, bond length grows and bond strength falls, so acidity rises: HF < HCl < HBr < HI. Across a period, electronegativity dominates: CH₄ < NH₃ < H₂O < HF. HF is weak (pKa 3.2) despite fluorine''s electronegativity because the H–F bond is very strong and F⁻ is small."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd492e7d9dbd97', 'les_53867f61064c3a', 'learn', 3, 'definition', '{"term":"Oxyacids, H–O–Y","body":"More electronegative Y pulls electron density from the O–H bond: HOI < HOBr < HOCl. More oxygens on Y spread the negative charge of the conjugate base by resonance: HClO < HClO₂ < HClO₃ < HClO₄ (pKa 7.5, 2.0, about −1, about −8)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e04e9227c39ff8', 'les_53867f61064c3a', 'learn', 4, 'worked_example', '{"title":"Why chloroacetic acid is stronger than acetic acid","steps":[{"latex":"\\text{CH}_3\\text{COOH: p}K_a = 4.74","explanation":""},{"latex":"\\text{ClCH}_2\\text{COOH: p}K_a = 2.85","explanation":""},{"latex":"\\Delta\\text{p}K_a \\approx 1.9","explanation":"About 80 times larger K_a."},{"latex":"\\text{Cl pulls charge from COO}^-","explanation":"Inductive effect stabilizes the base."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2becd039a7b7ca', 'les_53867f61064c3a', 'learn', 5, 'callout', '{"tone":"note","title":"Bases mirror acids","body":"A strong acid has a negligibly weak conjugate base. Amines are bases because the N lone pair can accept H⁺; electron-withdrawing groups near nitrogen make that lone pair less available and the base weaker."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6fddc5e4523451', 'les_53867f61064c3a', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Drug designers tune pKa with substituents so a molecule is charged or neutral at the pH of blood or the stomach, controlling absorption."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec04aace244aed', 'les_53867f61064c3a', 1, 'practice', 'numeric', 2, 'Chloroacetic acid has Ka = 1.4 × 10⁻³. Find its pKa, to two decimal places.', '{"answer":2.85,"tolerance":0.01}', '["pKa = −log Ka."]', '$-\log(1.4\times10^{-3}) = 2.85$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69c0b4c7b3e15d', 'les_53867f61064c3a', 2, 'practice', 'multiple_choice', 2, 'Which is the strongest acid?', '{"choices":["HF","HCl","HBr","HI"],"answer":3}', '["Down a group, bond strength decides."]', 'The H–I bond is longest and weakest.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fd492e7d9dbd97', 'les_53867f61064c3a', 3, 'practice', 'multiple_choice', 2, 'Which is the strongest acid?', '{"choices":["HOCl","HClO₂","HClO₃","HClO₄"],"answer":3}', '["Count the oxygens."]', 'Four oxygens spread the conjugate base''s charge most.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e04e9227c39ff8', 'les_53867f61064c3a', 4, 'practice', 'multiple_choice', 3, 'HOCl is stronger than HOBr because…', '{"choices":["Cl is larger","Cl is more electronegative and pulls density from O–H","HOBr has more oxygens","Br⁻ is more stable"],"answer":1}', '["Same structure; compare the central atom."]', 'Greater pull weakens the O–H bond and stabilizes OCl⁻.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2becd039a7b7ca', 'les_53867f61064c3a', 5, 'review', 'multiple_choice', 3, 'Trichloroacetic acid (pKa 0.7) vs acetic acid (4.74): the trend shows that…', '{"choices":["more Cl weakens the acid","electron-withdrawing groups strengthen acids","Cl donates electrons","size controls acidity"],"answer":1}', '["Each Cl pulls charge."]', 'Three Cl atoms stabilize the carboxylate strongly.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_53867f61064c3a', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_53867f61064c3a', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_53867f61064c3a', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);

-- Lesson: ap-acid-base-titrations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9a1963cdf30134', 'ap-acid-base-titrations', 'Acid-base titrations', 'Read titration curves for strong and weak acids, find concentrations from the equivalence point, and calculate pH in each region of a weak-acid titration.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3c76f4126a959f', 'les_9a1963cdf30134', 1, 'Use moles at equivalence to find an unknown concentration.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aba476b7f458f8', 'les_9a1963cdf30134', 2, 'Calculate pH at the start, half-equivalence, equivalence and past equivalence of a weak acid titrated with NaOH.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a2f7486ce6bb1', 'les_9a1963cdf30134', 3, 'Read pKa from a curve and choose an indicator whose range covers the equivalence pH.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c76f4126a959f', 'les_9a1963cdf30134', 'learn', 1, 'definition', '{"term":"Equivalence point","body":"The point where moles of added base equal the moles of acid originally present: $M_aV_a = M_bV_b$ for a 1:1 reaction. For a strong acid with a strong base the solution is neutral there (pH 7). For a weak acid, the solution holds only the conjugate base A⁻, so the pH is above 7."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aba476b7f458f8', 'les_9a1963cdf30134', 'learn', 2, 'definition', '{"term":"The four regions of a weak-acid curve","body":"(1) Start: weak acid only, use $K_a$. (2) Buffer region: HA and A⁻ both present, use Henderson–Hasselbalch. At half-equivalence [HA] = [A⁻] and pH = pKa. (3) Equivalence: A⁻ only, use $K_b = K_w/K_a$. (4) Past equivalence: excess OH⁻ controls the pH."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a2f7486ce6bb1', 'les_9a1963cdf30134', 'learn', 3, 'worked_example', '{"title":"25.0 mL of 0.100 M acetic acid (Ka 1.8 × 10⁻⁵) titrated with 0.100 M NaOH","steps":[{"latex":"\\text{Start: } [\\text{H}^+] = \\sqrt{K_aC}","explanation":""},{"latex":"= 1.34\\times10^{-3} \\Rightarrow \\text{pH } 2.87","explanation":""},{"latex":"\\text{12.5 mL: pH} = \\text{p}K_a = 4.74","explanation":"Half the acid is converted to A⁻."},{"latex":"\\text{25.0 mL: } [\\text{A}^-] = \\tfrac{0.00250}{0.0500}","explanation":"= 0.0500 M in 50.0 mL."},{"latex":"[\\text{OH}^-] = \\sqrt{K_b(0.0500)}","explanation":"K_b = 5.6 × 10⁻¹⁰."},{"latex":"\\Rightarrow \\text{pH } 8.72","explanation":"Basic at equivalence."},{"latex":"\\text{35.0 mL: excess OH}^- = 0.00100\\ \\text{mol}","explanation":""},{"latex":"[\\text{OH}^-] = \\tfrac{0.00100}{0.0600} \\Rightarrow \\text{pH } 12.22","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ed4bb7be64179', 'les_9a1963cdf30134', 'experiment', 4, 'activity', '{"activity":"titration","title":"Titration curve","params":{"acid":"weak","acidConc":0.1,"baseConc":0.1,"baseVolume":12.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_565879e0e7bc10', 'les_9a1963cdf30134', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Switch between strong and weak acid. The curves join past equivalence, but the weak acid starts higher, has a flat buffer region and a shorter, higher jump."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_864337f4003a54', 'les_9a1963cdf30134', 'learn', 6, 'definition', '{"term":"Indicators","body":"An indicator is itself a weak acid whose two forms differ in color; it changes over roughly pKa(In) ± 1. Pick one whose range covers the steep jump: phenolphthalein (8.2–10) for weak acid with strong base, methyl red (4.4–6.2) for weak base with strong acid."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a37d009017826b', 'les_9a1963cdf30134', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Titrations measure acidity in wine and vinegar, nitrogen in food (Kjeldahl method) and alkalinity in water treatment."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c76f4126a959f', 'les_9a1963cdf30134', 1, 'practice', 'numeric', 2, '20.0 mL of HCl needs 32.0 mL of 0.125 M NaOH to reach equivalence. Find [HCl] in M.', '{"answer":0.2,"tolerance":0.001,"unit":"M"}', '["Moles NaOH = moles HCl."]', '$0.125 \times 32.0 / 20.0 = 0.200$ M.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aba476b7f458f8', 'les_9a1963cdf30134', 2, 'practice', 'numeric', 2, 'A weak acid''s curve has pH 3.85 when half the equivalence volume has been added. What is its pKa?', '{"answer":3.85,"tolerance":0.01}', '["At half-equivalence [HA] = [A⁻]."]', 'pH = pKa there.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a2f7486ce6bb1', 'les_9a1963cdf30134', 3, 'practice', 'numeric', 3, 'In the acetic acid example, what is the pH after 20.0 mL of NaOH? Give two decimal places.', '{"answer":5.34,"tolerance":0.01}', '["Moles A⁻ = 0.00200, HA left = 0.00050.","Use Henderson–Hasselbalch."]', '$4.74 + \log 4 = 5.34$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4ed4bb7be64179', 'les_9a1963cdf30134', 4, 'practice', 'multiple_choice', 2, 'Titrating a weak acid with NaOH, the pH at equivalence is…', '{"choices":["below 7","exactly 7","above 7","equal to pKa"],"answer":2}', '["What species remains?"]', 'Only A⁻, a weak base.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_565879e0e7bc10', 'les_9a1963cdf30134', 5, 'review', 'multiple_choice', 3, 'Which indicator suits NH₃ titrated with HCl (equivalence pH ≈ 5.3)?', '{"choices":["phenolphthalein (8.2–10)","methyl red (4.4–6.2)","thymol blue (8.0–9.6)","alizarin yellow (10–12)"],"answer":1}', '["Match the range to the equivalence pH."]', 'Methyl red changes around pH 5.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9a1963cdf30134', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9a1963cdf30134', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9a1963cdf30134', (SELECT id FROM formulas WHERE slug = 'ph-scale'), 2);

-- Lesson: buffer-capacity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_514ce666f6eaa5', 'buffer-capacity', 'Buffer capacity', 'Define buffer capacity, calculate how much strong acid or base a buffer absorbs before its pH moves by one unit, and compare concentrated and dilute buffers.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_98ee5c648576e0', 'les_514ce666f6eaa5', 1, 'Define capacity as the amount of strong acid or base a buffer can absorb with little pH change.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_50de589a352f7a', 'les_514ce666f6eaa5', 2, 'Show that capacity grows with the amounts of HA and A⁻ and is largest when they are equal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_36c228536ee5b7', 'les_514ce666f6eaa5', 3, 'Calculate the pH after an addition and the amount needed for a one-unit change.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98ee5c648576e0', 'les_514ce666f6eaa5', 'learn', 1, 'definition', '{"term":"Capacity","body":"Buffer capacity is the amount of strong acid or base a buffer can neutralize before its pH changes significantly. Two buffers with the same ratio share a pH, but the one with more moles of each component has more capacity. Capacity toward base is limited by HA; toward acid, by A⁻."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50de589a352f7a', 'les_514ce666f6eaa5', 'learn', 2, 'worked_example', '{"title":"1.00 L of 0.10 M HA / 0.10 M A⁻: how much NaOH raises the pH by 1.00?","steps":[{"latex":"\\tfrac{0.10 + x}{0.10 - x} = 10","explanation":"The ratio must rise 10-fold."},{"latex":"0.10 + x = 1.0 - 10x","explanation":""},{"latex":"x = 0.0818\\ \\text{mol}","explanation":"About 82% of the HA is used up."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36c228536ee5b7', 'les_514ce666f6eaa5', 'learn', 3, 'worked_example', '{"title":"The same pH, but 0.010 M of each","steps":[{"latex":"x = 0.00818\\ \\text{mol}","explanation":"Ten times less capacity."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19a7d2b4b332e7', 'les_514ce666f6eaa5', 'experiment', 4, 'activity', '{"activity":"buffer","title":"Finding the capacity","params":{"acid":0.1,"base":0.1,"added":0.05}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_854f00c03da4a3', 'les_514ce666f6eaa5', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Step the added base up toward 0.10 mol. The pH creeps for a while, then jumps once the acetic acid is nearly gone. Repeat with 0.5 mol of each component."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_122d60259c3963', 'les_514ce666f6eaa5', 'learn', 6, 'callout', '{"tone":"note","title":"Why equal amounts work best","body":"At a 1:1 ratio, a given addition changes the log term least. With a 10:1 ratio, the minor component is used up quickly in one direction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f453470935b88', 'les_514ce666f6eaa5', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ocean carbonate buffering absorbs much of the CO₂ we emit; as its capacity is used, the oceans acidify measurably."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98ee5c648576e0', 'les_514ce666f6eaa5', 1, 'practice', 'numeric', 2, '0.050 mol NaOH is added to 1.00 L of 0.10 M acetic acid / 0.10 M acetate (pKa 4.74). Find the pH, to two decimal places.', '{"answer":5.22,"tolerance":0.01}', '["HA 0.05, A⁻ 0.15."]', '$4.74 + \log 3 = 5.22$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50de589a352f7a', 'les_514ce666f6eaa5', 2, 'practice', 'numeric', 3, 'How many moles of NaOH raise the pH of 1.00 L of 0.50 M HA / 0.50 M A⁻ by exactly 1 unit? Three decimal places.', '{"answer":0.409,"tolerance":0.002,"unit":"mol"}', '["Solve (0.50 + x)/(0.50 − x) = 10."]', '$x = 0.50 \cdot 9/11 = 0.409$ mol.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36c228536ee5b7', 'les_514ce666f6eaa5', 3, 'practice', 'multiple_choice', 2, 'Which buffer has the greatest capacity?', '{"choices":["0.01 M HA / 0.01 M A⁻","0.1 M HA / 0.1 M A⁻","1.0 M HA / 1.0 M A⁻","1.0 M HA / 0.01 M A⁻"],"answer":2}', '["Large and equal amounts."]', 'The most of both components.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19a7d2b4b332e7', 'les_514ce666f6eaa5', 4, 'practice', 'multiple_choice', 2, 'A buffer with [A⁻] much larger than [HA] resists added…', '{"choices":["base better than acid","acid better than base","both equally","neither"],"answer":1}', '["Which component neutralizes H⁺?"]', 'A⁻ consumes H⁺; HA is scarce for OH⁻.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_854f00c03da4a3', 'les_514ce666f6eaa5', 5, 'review', 'multiple_choice', 3, 'Two buffers have pH 4.74. Buffer X uses 0.5 M of each component and Y uses 0.05 M. Compared to Y, X has…', '{"choices":["higher pH","lower pH","ten times the capacity","the same capacity"],"answer":2}', '[]', 'Same ratio, ten times the moles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_514ce666f6eaa5', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_514ce666f6eaa5', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);

-- Lesson: buffer-properties
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6230bd52276115', 'buffer-properties', 'Properties of buffers', 'Identify buffer systems, prepare them by mixing or by partial neutralization, and explain why dilution barely changes a buffer''s pH.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c692f9def22bc3', 'les_6230bd52276115', 1, 'Recognize buffer pairs: weak acid with conjugate base, or weak base with conjugate acid.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ef5861be00fb0', 'les_6230bd52276115', 2, 'Prepare a buffer by partially neutralizing a weak acid with strong base.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b189417121f9f1', 'les_6230bd52276115', 3, 'Explain how a buffer neutralizes added H⁺ and OH⁻, and why dilution leaves pH nearly unchanged.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c692f9def22bc3', 'les_6230bd52276115', 'learn', 1, 'definition', '{"term":"What makes a buffer","body":"Significant amounts of both a weak acid and its conjugate base (HNO₂/NO₂⁻, NH₄⁺/NH₃, H₂PO₄⁻/HPO₄²⁻). The acid neutralizes added OH⁻, the base neutralizes added H⁺. A strong acid with its salt (HCl/NaCl) is not a buffer: Cl⁻ is too weak a base to take back protons."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ef5861be00fb0', 'les_6230bd52276115', 'learn', 2, 'definition', '{"term":"Two ways to make one","body":"Mix HA with a salt of A⁻, or start with HA alone and add strong base until part of it is converted to A⁻. Adding less than one equivalent of NaOH to a weak acid always produces a buffer, which is why the middle of a titration curve is flat."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b189417121f9f1', 'les_6230bd52276115', 'learn', 3, 'worked_example', '{"title":"0.30 mol acetic acid + 0.10 mol NaOH in 1.0 L","steps":[{"latex":"\\text{HA: } 0.30 - 0.10 = 0.20\\ \\text{mol}","explanation":"OH⁻ reacts completely."},{"latex":"\\text{A}^-: 0.10\\ \\text{mol}","explanation":""},{"latex":"\\text{pH} = 4.74 + \\log\\tfrac{0.10}{0.20}","explanation":""},{"latex":"= 4.44","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64455f0419ef14', 'les_6230bd52276115', 'learn', 4, 'definition', '{"term":"Dilution","body":"pH depends on the ratio $n_{\\text{A}^-}/n_{\\text{HA}}$. Diluting with water changes both concentrations by the same factor, so the ratio and the pH stay put (until the solution is so dilute that water''s own ions matter). Dilution does lower the capacity."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e6ed5840b8c8c', 'les_6230bd52276115', 'experiment', 5, 'activity', '{"activity":"buffer","title":"Buffer response","params":{"acid":0.2,"base":0.1,"added":0.02}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d80441b69e3ae', 'les_6230bd52276115', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Set equal acid and base, then add small amounts of strong acid and strong base. Compare the pH change of the buffer and of pure water side by side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e33b1593ca87ff', 'les_6230bd52276115', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Phosphate buffers (pKa 7.2) hold cell-culture media and biochemistry experiments near pH 7; blood relies on H₂CO₃/HCO₃⁻."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c692f9def22bc3', 'les_6230bd52276115', 1, 'practice', 'numeric', 2, 'Find the pH of the buffer made from 0.30 mol acetic acid and 0.10 mol NaOH in 1.0 L, to two decimal places.', '{"answer":4.44,"tolerance":0.01}', '["React first, then use the ratio."]', '$4.74 + \log 0.5 = 4.44$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ef5861be00fb0', 'les_6230bd52276115', 2, 'practice', 'numeric', 3, '0.20 mol NH₃ is mixed with 0.050 mol HCl in 500 mL. Find the pH (NH₄⁺ pKa 9.25), to two decimal places.', '{"answer":9.73,"tolerance":0.01}', '["HCl converts NH₃ to NH₄⁺.","Base is NH₃, acid is NH₄⁺."]', 'NH₃ 0.15, NH₄⁺ 0.050: $9.25 + \log 3 = 9.73$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b189417121f9f1', 'les_6230bd52276115', 3, 'practice', 'multiple_choice', 2, 'Which mixture is a buffer?', '{"choices":["HNO₃ + KNO₃","NH₃ + NH₄Cl","NaOH + NaCl","HCl + KCl"],"answer":1}', '["Look for a weak conjugate pair."]', 'NH₄⁺ and NH₃ are a weak acid–base pair.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64455f0419ef14', 'les_6230bd52276115', 4, 'practice', 'multiple_choice', 2, 'A buffer is diluted to ten times its volume with water. Its pH…', '{"choices":["rises by 1","falls by 1","stays about the same","becomes 7"],"answer":2}', '["What happens to the ratio?"]', 'The ratio is unchanged.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e6ed5840b8c8c', 'les_6230bd52276115', 5, 'review', 'multiple_choice', 3, 'Which added amount of NaOH turns 0.10 mol HF into a buffer?', '{"choices":["0.050 mol","0.10 mol","0.15 mol","0.20 mol"],"answer":0}', '["You need both HF and F⁻ left."]', 'Only less than 0.10 mol leaves both forms.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6230bd52276115', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6230bd52276115', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);

-- Lesson: cell-potential-free-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4e7f769cdb7a17', 'cell-potential-free-energy', 'Cell potential and free energy', 'Connect standard cell potential to free energy and the equilibrium constant with ΔG° = −nFE° and ΔG° = −RT ln K.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fe553e52fbf5ff', 'les_4e7f769cdb7a17', 1, 'Use ΔG° = −nFE° to convert between cell potential and free energy.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a853d5a73af951', 'les_4e7f769cdb7a17', 2, 'Relate E° > 0 to ΔG° < 0 and K > 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0d255e25931f0', 'les_4e7f769cdb7a17', 3, 'Calculate K from E° for a redox reaction.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe553e52fbf5ff', 'les_4e7f769cdb7a17', 'learn', 1, 'definition', '{"term":"Electrical work","body":"A cell pushing $n$ moles of electrons through potential $E$ does $nFE$ of work, with $F = 96{,}485$ C/mol (the Faraday constant). The maximum work equals the free-energy decrease, so $\\Delta G^\\circ = -nFE^\\circ$. A positive $E^\\circ$ means a favorable (galvanic) reaction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a853d5a73af951', 'les_4e7f769cdb7a17', 'learn', 2, 'definition', '{"term":"Three equivalent signals","body":"$E^\\circ > 0 \\Leftrightarrow \\Delta G^\\circ < 0 \\Leftrightarrow K > 1$. Combining with $\\Delta G^\\circ = -RT\\ln K$ gives $\\ln K = \\frac{nFE^\\circ}{RT}$, so even modest potentials give huge K."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0d255e25931f0', 'les_4e7f769cdb7a17', 'learn', 3, 'worked_example', '{"title":"Zn | Zn²⁺ || Cu²⁺ | Cu, E° = 1.10 V, n = 2","steps":[{"latex":"\\Delta G^\\circ = -2(96{,}485)(1.10)","explanation":""},{"latex":"= -2.12\\times10^5\\ \\text{J} = -212\\ \\text{kJ}","explanation":""},{"latex":"\\ln K = \\tfrac{2(96{,}485)(1.10)}{8.314(298)} = 85.7","explanation":""},{"latex":"K = 1.6\\times10^{37}","explanation":"The reaction goes to completion."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85118b148d8bc2', 'les_4e7f769cdb7a17', 'experiment', 4, 'activity', '{"activity":"galvanic-cell","title":"E° and ΔG° for a cell","params":{"left":"Zn","right":"Cu","leftConc":1,"rightConc":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86cb68b6d513f9', 'les_4e7f769cdb7a17', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Swap in different metal pairs at 1 M and compare the ΔG readout with −nFE° for each. Pairs farther apart in the table give larger potentials and more negative ΔG."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d992c9ef7da217', 'les_4e7f769cdb7a17', 'learn', 6, 'callout', '{"tone":"warning","title":"Units","body":"$nFE$ comes out in joules (C × V = J). Divide by 1000 before comparing with ΔG° in kJ. Don''t multiply E° by stoichiometric coefficients: n already accounts for the electrons."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_876b7bc9603724', 'les_4e7f769cdb7a17', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Battery makers pick electrode pairs for large E°, and fuel cells turn the free energy of 2H₂ + O₂ → 2H₂O directly into electricity rather than heat."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fe553e52fbf5ff', 'les_4e7f769cdb7a17', 1, 'practice', 'numeric', 2, 'Find ΔG° for Cu | Cu²⁺ || Ag⁺ | Ag (E° = 0.46 V, n = 2), in kJ to one decimal place.', '{"answer":-88.8,"tolerance":0.2,"unit":"kJ"}', '["−nFE°, then divide by 1000."]', '$-2(96{,}485)(0.46) = -88{,}800$ J.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a853d5a73af951', 'les_4e7f769cdb7a17', 2, 'practice', 'numeric', 3, 'Find K at 298 K for a reaction with E° = 0.10 V and n = 1, to the nearest whole number.', '{"answer":49,"tolerance":1}', '["ln K = nFE°/RT."]', '$\ln K = 9648.5/2477.6 = 3.89$; $K = 49$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0d255e25931f0', 'les_4e7f769cdb7a17', 3, 'practice', 'multiple_choice', 2, 'A cell has E° < 0. Then…', '{"choices":["ΔG° < 0, K > 1","ΔG° > 0, K < 1","ΔG° = 0","the cell is galvanic"],"answer":1}', '[]', 'The reaction as written is unfavorable.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_85118b148d8bc2', 'les_4e7f769cdb7a17', 4, 'practice', 'multiple_choice', 2, 'F, the Faraday constant, is…', '{"choices":["the charge on one electron","the charge on one mole of electrons","R × T","volts per mole"],"answer":1}', '[]', '96,485 C/mol.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86cb68b6d513f9', 'les_4e7f769cdb7a17', 5, 'review', 'multiple_choice', 3, 'Doubling all coefficients of a cell reaction changes…', '{"choices":["E° and ΔG°","ΔG° but not E°","E° but not ΔG°","neither"],"answer":1}', '["n doubles; E° is intensive."]', 'ΔG° doubles with n; E° stays.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4e7f769cdb7a17', (SELECT id FROM concepts WHERE slug = 'electrochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4e7f769cdb7a17', (SELECT id FROM formulas WHERE slug = 'electrochemistry'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4e7f769cdb7a17', (SELECT id FROM formulas WHERE slug = 'free-energy'), 2);

-- Lesson: coupled-reactions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9d238b459f8759', 'coupled-reactions', 'Coupled reactions', 'Drive unfavorable reactions by coupling them to favorable ones with a shared intermediate, by electrical work or by light, and add free energies of coupled steps.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_56ab306ed89561', 'les_9d238b459f8759', 1, 'Explain that free energies of coupled reactions add like enthalpies in Hess''s law.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6b383f73e5437e', 'les_9d238b459f8759', 2, 'Calculate the overall ΔG° of a coupled process.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_014107bff2eded', 'les_9d238b459f8759', 3, 'Identify external energy sources (electricity, light) that drive unfavorable processes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56ab306ed89561', 'les_9d238b459f8759', 'learn', 1, 'definition', '{"term":"Coupling","body":"A reaction with $\\Delta G^\\circ > 0$ can be made to proceed if it shares an intermediate with a reaction whose $\\Delta G^\\circ$ is more negative. The overall $\\Delta G^\\circ$ is the sum, and the combined process is favorable if the sum is negative. Other routes: electrical work (electrolysis) or absorbed light (photosynthesis)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b383f73e5437e', 'les_9d238b459f8759', 'learn', 2, 'worked_example', '{"title":"Smelting copper from Cu₂S","steps":[{"latex":"\\text{Cu}_2\\text{S} \\to 2\\text{Cu} + \\text{S}","explanation":"ΔG° = +86.2 kJ"},{"latex":"\\text{S} + \\text{O}_2 \\to \\text{SO}_2","explanation":"ΔG° = −300.1 kJ"},{"latex":"\\Delta G^\\circ_{\\text{total}} = -213.9\\ \\text{kJ}","explanation":"Sulfur is the shared intermediate."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_014107bff2eded', 'les_9d238b459f8759', 'learn', 3, 'worked_example', '{"title":"ATP drives glutamine synthesis in cells","steps":[{"latex":"\\text{Glu} + \\text{NH}_3 \\to \\text{Gln}","explanation":"ΔG° = +14.2 kJ"},{"latex":"\\text{ATP} \\to \\text{ADP} + \\text{P}_i","explanation":"ΔG° = −30.5 kJ"},{"latex":"\\Delta G^\\circ = -16.3\\ \\text{kJ}","explanation":"A phosphorylated intermediate links them."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_603815e651c6ca', 'les_9d238b459f8759', 'learn', 4, 'callout', '{"tone":"note","title":"Coupling needs a mechanism","body":"You can''t just add two reactions on paper. They are coupled only if they actually share an intermediate or happen in the same molecular machinery, as with an enzyme."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a17cd7b06e6a5f', 'les_9d238b459f8759', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Metal refining, recharging batteries, photosynthesis and almost all of metabolism: your body uses ATP hydrolysis to build proteins, contract muscles and pump ions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_56ab306ed89561', 'les_9d238b459f8759', 1, 'practice', 'numeric', 2, 'Find the overall ΔG° for the Cu₂S smelting process.', '{"answer":-213.9,"tolerance":0.1,"unit":"kJ"}', '["Add the two steps."]', '$86.2 + (-300.1) = -213.9$ kJ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b383f73e5437e', 'les_9d238b459f8759', 2, 'practice', 'numeric', 3, 'A step has ΔG° = +45.0 kJ. What is the minimum number of ATP hydrolyses (−30.5 kJ each) needed to drive it?', '{"answer":2}', '["The sum must be negative."]', 'One gives +14.5 kJ; two give −16.0 kJ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_014107bff2eded', 'les_9d238b459f8759', 3, 'practice', 'multiple_choice', 2, 'Coupled reactions are favorable overall when…', '{"choices":["each step is favorable","the sum of ΔG° values is negative","ΔH is positive","K for each step exceeds 1"],"answer":1}', '[]', 'Free energies add.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_603815e651c6ca', 'les_9d238b459f8759', 4, 'practice', 'multiple_choice', 2, 'Which supplies the energy for photosynthesis''s unfavorable sugar synthesis?', '{"choices":["heat","light","ATP from outside the plant","entropy"],"answer":1}', '[]', 'Absorbed photons do the work.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a17cd7b06e6a5f', 'les_9d238b459f8759', 5, 'review', 'multiple_choice', 3, 'What makes two reactions genuinely coupled?', '{"choices":["They happen in the same flask","They share an intermediate","They have the same ΔH","Both have K > 1"],"answer":1}', '[]', 'A shared intermediate or mechanism.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9d238b459f8759', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9d238b459f8759', (SELECT id FROM formulas WHERE slug = 'free-energy'), 1);

-- Lesson: electrolysis-faraday
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_235c6a4279e6a9', 'electrolysis-faraday', 'Electrolysis and Faraday''s law', 'Describe electrolytic cells, predict electrode products, and use current, time and Faraday''s constant to calculate the mass deposited or the time required.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_787a8d4182eabb', 'les_235c6a4279e6a9', 1, 'Compare electrolytic with galvanic cells: an outside source drives a reaction with E° < 0.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bdab8488be6de6', 'les_235c6a4279e6a9', 2, 'Use q = It and n(e⁻) = q/F to relate charge to moles of product.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9eca173a487d96', 'les_235c6a4279e6a9', 3, 'Calculate mass deposited, current needed or time required.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_787a8d4182eabb', 'les_235c6a4279e6a9', 'learn', 1, 'definition', '{"term":"Electrolytic cells","body":"A power supply pushes electrons to drive a nonspontaneous reaction ($E^\\circ < 0$, $\\Delta G^\\circ > 0$). The applied voltage must exceed $|E^\\circ|$. Oxidation still happens at the anode and reduction at the cathode, but now the anode is positive (connected to the supply''s + terminal)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bdab8488be6de6', 'les_235c6a4279e6a9', 'learn', 2, 'definition', '{"term":"Faraday''s law","body":"Charge $q = It$ (coulombs = amperes × seconds). Moles of electrons $= q/F$. The half-reaction gives moles of product per mole of electrons: Cu²⁺ + 2e⁻ → Cu needs 2, Al³⁺ + 3e⁻ → Al needs 3."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9eca173a487d96', 'les_235c6a4279e6a9', 'learn', 3, 'worked_example', '{"title":"Plating copper at 2.00 A for 30.0 min","steps":[{"latex":"q = 2.00 \\times 1800 = 3600\\ \\text{C}","explanation":""},{"latex":"n_{e^-} = \\tfrac{3600}{96{,}485} = 0.0373\\ \\text{mol}","explanation":""},{"latex":"n_{\\text{Cu}} = 0.0187\\ \\text{mol}","explanation":"Two electrons per Cu."},{"latex":"m = 0.0187 \\times 63.55 = 1.19\\ \\text{g}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_23f420e5ceda51', 'les_235c6a4279e6a9', 'learn', 4, 'worked_example', '{"title":"Time to make 1.00 kg Al at 100,000 A","steps":[{"latex":"n_{\\text{Al}} = \\tfrac{1000}{26.98} = 37.1\\ \\text{mol}","explanation":""},{"latex":"n_{e^-} = 3(37.1) = 111.2\\ \\text{mol}","explanation":""},{"latex":"t = \\tfrac{111.2 \\times 96{,}485}{100{,}000}","explanation":""},{"latex":"= 107\\ \\text{s}","explanation":"Smelters run huge currents nonstop."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f33cbaf26f7258', 'les_235c6a4279e6a9', 'learn', 5, 'callout', '{"tone":"note","title":"Which product forms?","body":"In molten salts the metal cation is reduced and the anion oxidized. In water, H₂O can be reduced to H₂ or oxidized to O₂ instead; compare reduction potentials. Electrolyzing aqueous NaCl gives H₂ at the cathode, not sodium."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62bf6d9dd966e4', 'les_235c6a4279e6a9', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Aluminum production (Hall–Héroult process), chlorine and NaOH from brine, electroplating chrome and gold, and charging every rechargeable battery."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_787a8d4182eabb', 'les_235c6a4279e6a9', 1, 'practice', 'numeric', 2, 'What mass of silver (107.87 g/mol) plates out at 0.500 A in 1.00 h? Two decimal places.', '{"answer":2.01,"tolerance":0.01,"unit":"g"}', '["q = It with t in seconds.","Ag⁺ + e⁻ → Ag."]', '$1800/96{,}485 = 0.01866$ mol; × 107.87 = 2.01 g.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bdab8488be6de6', 'les_235c6a4279e6a9', 2, 'practice', 'numeric', 3, 'How many minutes does it take to deposit 5.00 g of zinc (65.38 g/mol) at 3.00 A? One decimal place.', '{"answer":82,"tolerance":0.2,"unit":"min"}', '["Zn²⁺ + 2e⁻ → Zn.","t = n(e⁻)F/I."]', '$0.0765 \times 2 \times 96{,}485 / 3.00 = 4920$ s = 82.0 min.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9eca173a487d96', 'les_235c6a4279e6a9', 3, 'practice', 'multiple_choice', 2, 'In an electrolytic cell, ΔG° is…', '{"choices":["negative","positive","zero","always −nFE"],"answer":1}', '[]', 'An outside source drives a nonspontaneous reaction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_23f420e5ceda51', 'les_235c6a4279e6a9', 4, 'practice', 'multiple_choice', 2, 'The same charge passes through Ag⁺ and Cu²⁺ cells in series. The ratio of moles Ag : Cu deposited is…', '{"choices":["1 : 1","1 : 2","2 : 1","3 : 2"],"answer":2}', '["Compare electrons per atom."]', 'Ag needs 1 e⁻, Cu needs 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f33cbaf26f7258', 'les_235c6a4279e6a9', 5, 'review', 'multiple_choice', 3, 'Electrolysis of aqueous NaCl produces at the cathode…', '{"choices":["Na(s)","H₂(g)","Cl₂(g)","O₂(g)"],"answer":1}', '["Water is easier to reduce than Na⁺."]', 'H₂O is reduced to H₂ and OH⁻.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_235c6a4279e6a9', (SELECT id FROM concepts WHERE slug = 'electrochemistry'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_235c6a4279e6a9', (SELECT id FROM concepts WHERE slug = 'stoichiometry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_235c6a4279e6a9', (SELECT id FROM formulas WHERE slug = 'electrochemistry'), 1);

-- Lesson: free-energy-equilibrium
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0ebb7a55bbe096', 'free-energy-equilibrium', 'Free energy and equilibrium', 'Relate ΔG° to the equilibrium constant with ΔG° = −RT ln K, and use ΔG = ΔG° + RT ln Q to predict which way a mixture will shift.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4a5c60134bde39', 'les_0ebb7a55bbe096', 1, 'Convert between ΔG° and K with ΔG° = −RT ln K.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c6d501fb72cfc8', 'les_0ebb7a55bbe096', 2, 'Connect the sign of ΔG° to K > 1 or K < 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_39bc7075462faa', 'les_0ebb7a55bbe096', 3, 'Use ΔG = ΔG° + RT ln Q for nonstandard mixtures.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a5c60134bde39', 'les_0ebb7a55bbe096', 'learn', 1, 'definition', '{"term":"The link","body":"$\\Delta G^\\circ = -RT\\ln K$ with $R = 8.314$ J/(mol·K). Negative ΔG° means K > 1 (products favored at equilibrium); positive ΔG° means K < 1. Because the relationship is exponential, every 5.7 kJ at 298 K changes K by a factor of 10."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6d501fb72cfc8', 'les_0ebb7a55bbe096', 'learn', 2, 'worked_example', '{"title":"K for the Haber process at 298 K (ΔG° = −33.0 kJ)","steps":[{"latex":"\\ln K = \\tfrac{33{,}000}{8.314 \\times 298}","explanation":""},{"latex":"= 13.32","explanation":""},{"latex":"K = e^{13.32} = 6.1\\times10^5","explanation":"Strongly product-favored."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_39bc7075462faa', 'les_0ebb7a55bbe096', 'learn', 3, 'worked_example', '{"title":"K when ΔG° = +10.0 kJ at 298 K","steps":[{"latex":"\\ln K = -\\tfrac{10{,}000}{2478}","explanation":"RT = 2478 J."},{"latex":"K = e^{-4.04} = 0.018","explanation":"Reactants favored, but not overwhelmingly."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8dc2774cbfcfb', 'les_0ebb7a55bbe096', 'learn', 4, 'definition', '{"term":"Nonstandard conditions","body":"$\\Delta G = \\Delta G^\\circ + RT\\ln Q$. If $Q < K$, ΔG < 0 and the forward reaction proceeds; if $Q > K$, ΔG > 0 and it runs in reverse; at $Q = K$, ΔG = 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_05368989406806', 'les_0ebb7a55bbe096', 'learn', 5, 'worked_example', '{"title":"Haber mixture with Q = 1.0 × 10⁷ at 298 K","steps":[{"latex":"\\Delta G = -33.0 + 2.478\\ln(10^7)","explanation":"kJ"},{"latex":"= -33.0 + 39.9 = +6.9\\ \\text{kJ}","explanation":"Q > K: NH₃ decomposes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fbe4ddbc653a9', 'les_0ebb7a55bbe096', 'experiment', 6, 'activity', '{"activity":"free-energy","title":"K from ΔG°","params":{"dH":-92.2,"dS":-198.7,"T":298}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc584f7adb43f7', 'les_0ebb7a55bbe096', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Biochemists quote ΔG° for metabolic steps, but cells keep Q far from K so even steps with positive ΔG° run forward."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4a5c60134bde39', 'les_0ebb7a55bbe096', 1, 'practice', 'numeric', 2, 'Find K at 298 K for ΔG° = −5.0 kJ, to one decimal place.', '{"answer":7.5,"tolerance":0.1}', '["K = e^(−ΔG°/RT); RT = 2478 J."]', '$e^{5000/2478} = e^{2.02} = 7.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6d501fb72cfc8', 'les_0ebb7a55bbe096', 2, 'practice', 'numeric', 3, 'A reaction has K = 1.0 × 10⁻⁵ at 298 K. Find ΔG° in kJ, to one decimal place.', '{"answer":28.5,"tolerance":0.1,"unit":"kJ"}', '["ΔG° = −RT ln K."]', '$-(8.314)(298)\ln(10^{-5}) = +28.5$ kJ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_39bc7075462faa', 'les_0ebb7a55bbe096', 3, 'practice', 'numeric', 3, 'For the Haber process (ΔG° = −33.0 kJ), find ΔG at 298 K when Q = 100, to one decimal place.', '{"answer":-21.6,"tolerance":0.1,"unit":"kJ"}', '["Add RT ln Q in kJ."]', '$-33.0 + 2.478(4.605) = -21.6$ kJ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f8dc2774cbfcfb', 'les_0ebb7a55bbe096', 4, 'practice', 'multiple_choice', 2, 'If ΔG° > 0, then…', '{"choices":["K > 1","K < 1","K = 1","K = 0"],"answer":1}', '[]', '$\ln K < 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_05368989406806', 'les_0ebb7a55bbe096', 5, 'review', 'multiple_choice', 3, 'At equilibrium…', '{"choices":["ΔG° = 0","ΔG = 0","Q = 0","K = 1 always"],"answer":1}', '["ΔG° is a fixed property of the reaction."]', 'ΔG = 0 at Q = K; ΔG° keeps its value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0ebb7a55bbe096', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0ebb7a55bbe096', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0ebb7a55bbe096', (SELECT id FROM formulas WHERE slug = 'free-energy'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0ebb7a55bbe096', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 2);

-- Lesson: gibbs-free-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3aaa8efcc8116c', 'gibbs-free-energy', 'Gibbs free energy and thermodynamic favorability', 'Combine enthalpy and entropy into ΔG = ΔH − TΔS, decide whether a process is thermodynamically favorable, and find the temperature where favorability switches.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0545bda5aa3b79', 'les_3aaa8efcc8116c', 1, 'Calculate ΔG° from ΔH° and ΔS° with consistent units.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_86b007586f2ff6', 'les_3aaa8efcc8116c', 2, 'Classify the four sign combinations of ΔH and ΔS by temperature dependence.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0dc4713e6f02c', 'les_3aaa8efcc8116c', 3, 'Calculate the crossover temperature T = ΔH°/ΔS°.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0545bda5aa3b79', 'les_3aaa8efcc8116c', 'learn', 1, 'definition', '{"term":"Gibbs free energy","body":"$\\Delta G = \\Delta H - T\\Delta S$ at constant temperature and pressure. $\\Delta G < 0$: thermodynamically favorable (proceeds without continuous outside energy). $\\Delta G > 0$: the reverse is favorable. $\\Delta G = 0$: equilibrium. The $-T\\Delta S$ term accounts for the entropy change of the surroundings."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86b007586f2ff6', 'les_3aaa8efcc8116c', 'learn', 2, 'worked_example', '{"title":"Haber process at 298 K: ΔH° = −92.2 kJ, ΔS° = −198.7 J/K","steps":[{"latex":"\\Delta S^\\circ = -0.1987\\ \\text{kJ/K}","explanation":"Convert to kJ first."},{"latex":"\\Delta G^\\circ = -92.2 - 298(-0.1987)","explanation":""},{"latex":"= -92.2 + 59.2 = -33.0\\ \\text{kJ}","explanation":"Favorable at room temperature."},{"latex":"T = \\tfrac{-92.2}{-0.1987} = 464\\ \\text{K}","explanation":"Above this, ΔG° > 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0dc4713e6f02c', 'les_3aaa8efcc8116c', 'experiment', 3, 'activity', '{"activity":"free-energy","title":"ΔG° against temperature","params":{"dH":-92.2,"dS":-198.7,"T":298}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83054afdc4aa71', 'les_3aaa8efcc8116c', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Drag the temperature past 464 K and watch ΔG° change sign. Then flip ΔS° to positive and see the line slope downward instead."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9177ec5bed51f8', 'les_3aaa8efcc8116c', 'learn', 5, 'definition', '{"term":"The four cases","body":"ΔH < 0, ΔS > 0: favorable at all T. ΔH > 0, ΔS < 0: never favorable. ΔH < 0, ΔS < 0: favorable at low T (enthalpy-driven). ΔH > 0, ΔS > 0: favorable at high T (entropy-driven), such as melting ice above 273 K."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d790ebfd5ecfe', 'les_3aaa8efcc8116c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Limestone kilns run above about 1100 K because CaCO₃ → CaO + CO₂ is entropy-driven; ammonia plants balance a favorable low temperature against a slow rate."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0545bda5aa3b79', 'les_3aaa8efcc8116c', 1, 'practice', 'numeric', 2, 'For CaCO₃ → CaO + CO₂, ΔH° = +178.3 kJ and ΔS° = +159.0 J/K. Find ΔG° at 298 K, to one decimal place.', '{"answer":130.9,"tolerance":0.2,"unit":"kJ"}', '["Convert ΔS° to kJ/K."]', '$178.3 - 298(0.1590) = 130.9$ kJ: not favorable.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86b007586f2ff6', 'les_3aaa8efcc8116c', 2, 'practice', 'numeric', 3, 'Above what temperature does CaCO₃ decomposition become favorable? Nearest kelvin.', '{"answer":1121,"tolerance":2,"unit":"K"}', '["Set ΔG° = 0."]', '$178{,}300 / 159.0 = 1121$ K.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0dc4713e6f02c', 'les_3aaa8efcc8116c', 3, 'practice', 'multiple_choice', 2, 'ΔH > 0 and ΔS > 0. The process is favorable…', '{"choices":["at all temperatures","at high temperatures","at low temperatures","never"],"answer":1}', '["Which term wins as T grows?"]', '−TΔS eventually outweighs ΔH.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_83054afdc4aa71', 'les_3aaa8efcc8116c', 4, 'practice', 'multiple_choice', 2, 'ΔG < 0 tells you a reaction…', '{"choices":["is fast","is thermodynamically favorable","is exothermic","has a large Ea"],"answer":1}', '[]', 'It says nothing about rate.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9177ec5bed51f8', 'les_3aaa8efcc8116c', 5, 'review', 'multiple_choice', 3, 'Water freezing at −10 °C has which signs?', '{"choices":["ΔH > 0, ΔS > 0","ΔH < 0, ΔS < 0","ΔH < 0, ΔS > 0","ΔH > 0, ΔS < 0"],"answer":1}', '["Freezing releases heat and orders molecules."]', 'Enthalpy-driven, favorable below 273 K.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3aaa8efcc8116c', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3aaa8efcc8116c', (SELECT id FROM formulas WHERE slug = 'free-energy'), 1);

-- Lesson: henderson-hasselbalch
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0b4321bb3f3822', 'henderson-hasselbalch', 'Henderson–Hasselbalch equation', 'Derive the Henderson–Hasselbalch equation from Ka, use it to find buffer pH, and design a buffer to hit a target pH.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_be8a38efd549c7', 'les_0b4321bb3f3822', 1, 'Derive pH = pKa + log([A⁻]/[HA]) from the Ka expression.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d488103fd1f190', 'les_0b4321bb3f3822', 2, 'Use moles or concentrations in the ratio, since both share one volume.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c09b6a070036d', 'les_0b4321bb3f3822', 3, 'Design a buffer: choose an acid by pKa and calculate the base-to-acid ratio and mass of salt needed.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be8a38efd549c7', 'les_0b4321bb3f3822', 'learn', 1, 'definition', '{"term":"Derivation","body":"Start from $K_a = \\frac{[\\text{H}_3\\text{O}^+][\\text{A}^-]}{[\\text{HA}]}$, take $-\\log$ of both sides and rearrange: $\\text{pH} = \\text{p}K_a + \\log\\frac{[\\text{A}^-]}{[\\text{HA}]}$. It assumes the initial amounts barely change by ionization, which holds when both are much larger than $K_a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d488103fd1f190', 'les_0b4321bb3f3822', 'learn', 2, 'worked_example', '{"title":"Design a pH 5.00 acetate buffer from 1.00 L of 0.10 M acetic acid","steps":[{"latex":"\\log\\tfrac{[\\text{A}^-]}{[\\text{HA}]} = 5.00 - 4.74","explanation":"= 0.26."},{"latex":"\\tfrac{[\\text{A}^-]}{[\\text{HA}]} = 10^{0.26} = 1.82","explanation":""},{"latex":"n_{\\text{A}^-} = 1.82(0.10) = 0.182\\ \\text{mol}","explanation":""},{"latex":"m = 0.182 \\times 82.03 = 14.9\\ \\text{g}","explanation":"Mass of NaCH₃COO to dissolve."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c09b6a070036d', 'les_0b4321bb3f3822', 'learn', 3, 'worked_example', '{"title":"pH of 0.30 M NH₃ with 0.20 M NH₄Cl (NH₄⁺ pKa 9.25)","steps":[{"latex":"\\text{pH} = 9.25 + \\log\\tfrac{0.30}{0.20}","explanation":"NH₃ is the base, NH₄⁺ the acid."},{"latex":"= 9.43","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_79e0d90b5f178f', 'les_0b4321bb3f3822', 'learn', 4, 'callout', '{"tone":"warning","title":"Common mistake","body":"Put the base on top. Writing $\\log\\frac{[\\text{HA}]}{[\\text{A}^-]}$ flips the sign of the correction. Sanity check: more base than acid must give pH above pKa."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85c7b459dd80d4', 'les_0b4321bb3f3822', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Blood: the H₂CO₃/HCO₃⁻ pair has pKa 6.10 at body temperature, so pH 7.40 needs [HCO₃⁻]/[H₂CO₃] = 20. Doctors read acid–base disorders straight from this ratio."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be8a38efd549c7', 'les_0b4321bb3f3822', 1, 'practice', 'numeric', 2, 'Find the pH of 0.30 M NH₃ with 0.20 M NH₄Cl (pKa 9.25), to two decimal places.', '{"answer":9.43,"tolerance":0.01}', '["Base over acid."]', '$9.25 + \log 1.5 = 9.43$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d488103fd1f190', 'les_0b4321bb3f3822', 2, 'practice', 'numeric', 3, 'Blood buffer: pKa 6.10, pH 7.40. Find [HCO₃⁻]/[H₂CO₃], to the nearest whole number.', '{"answer":20,"tolerance":0.5}', '["Ratio = 10^(pH − pKa)."]', '$10^{1.30} = 20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c09b6a070036d', 'les_0b4321bb3f3822', 3, 'practice', 'numeric', 3, 'How many grams of NaCH₃COO (82.03 g/mol) must be added to 1.00 L of 0.10 M acetic acid to make a pH 5.00 buffer? One decimal place.', '{"answer":14.9,"tolerance":0.2,"unit":"g"}', '["Ratio 1.82.","Moles × molar mass."]', '$0.182 \times 82.03 = 14.9$ g.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_79e0d90b5f178f', 'les_0b4321bb3f3822', 4, 'practice', 'multiple_choice', 2, 'To make a pH 9.0 buffer, the best acid has pKa…', '{"choices":["4.74 (acetic)","7.2 (H₂PO₄⁻)","9.25 (NH₄⁺)","3.2 (HF)"],"answer":2}', '["Closest pKa wins."]', 'Within 1 unit of the target pH.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_85c7b459dd80d4', 'les_0b4321bb3f3822', 5, 'review', 'multiple_choice', 3, 'A buffer has [A⁻]/[HA] = 0.1. Its pH is…', '{"choices":["pKa + 1","pKa − 1","pKa","10 × pKa"],"answer":1}', '[]', 'log 0.1 = −1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0b4321bb3f3822', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0b4321bb3f3822', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);

-- Lesson: intro-entropy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_796775d08a585f', 'intro-entropy', 'Introduction to entropy', 'Describe entropy as the dispersal of matter and energy over microstates, and predict the sign of ΔS for physical and chemical changes.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b2ca58b93c56c', 'les_796775d08a585f', 1, 'Connect entropy to the number of microstates with S = k ln W.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_423413f5328992', 'les_796775d08a585f', 2, 'Predict the sign of ΔS from phase changes, moles of gas, dissolving, temperature and molecular complexity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_331e757515bdb4', 'les_796775d08a585f', 3, 'Explain why spontaneous processes spread matter and energy out.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b2ca58b93c56c', 'les_796775d08a585f', 'learn', 1, 'definition', '{"term":"Entropy and microstates","body":"A microstate is one specific arrangement of particles and their energies that matches what we observe. Entropy measures how many there are: $S = k\\ln W$, where $k = 1.38\\times10^{-23}$ J/K. Arrangements that can happen in more ways are more probable, so isolated systems drift toward higher entropy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_423413f5328992', 'les_796775d08a585f', 'learn', 2, 'worked_example', '{"title":"Four particles in a box split into two halves","steps":[{"latex":"2^4 = 16\\ \\text{arrangements}","explanation":"Each particle can be left or right."},{"latex":"W(4\\text{ left}) = 1","explanation":"Probability 1/16."},{"latex":"W(2\\text{ left}) = \\binom{4}{2} = 6","explanation":"Probability 6/16: the most likely split."},{"latex":"10^{23}\\text{ particles} \\Rightarrow \\text{even split}","explanation":"The odds of anything else become negligible."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_331e757515bdb4', 'les_796775d08a585f', 'experiment', 3, 'activity', '{"activity":"microstates","title":"Counting microstates","params":{"particles":10,"left":5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_49a289c3eba6bc', 'les_796775d08a585f', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"With 10 particles, compare all-on-the-left (W = 1) with the 5–5 split (W = 252). Then raise N to 30 and watch the distribution narrow around the middle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c64fab3a1e016d', 'les_796775d08a585f', 'learn', 5, 'definition', '{"term":"Predicting the sign of ΔS","body":"Entropy increases when: solid → liquid → gas; a reaction makes more moles of gas; a solid or liquid dissolves (usually); temperature rises; molecules get larger or more flexible. Moles of gas usually dominate a reaction''s ΔS."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d97b395abf524b', 'les_796775d08a585f', 'learn', 6, 'worked_example', '{"title":"Sign of ΔS for 2 SO₂(g) + O₂(g) → 2 SO₃(g)","steps":[{"latex":"3\\ \\text{mol gas} \\to 2\\ \\text{mol gas}","explanation":""},{"latex":"\\Delta S < 0","explanation":"Fewer gas particles, fewer microstates."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52839bb8bf0135', 'les_796775d08a585f', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ice melting on a warm day, perfume spreading through a room and a gas expanding into a vacuum all happen with no energy push: each simply has overwhelmingly more microstates on the other side."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b2ca58b93c56c', 'les_796775d08a585f', 1, 'practice', 'numeric', 2, 'Six particles share two halves of a box. How many arrangements put exactly 3 on the left?', '{"answer":20}', '["Use C(6, 3)."]', '$\binom{6}{3} = 20$ of 64 arrangements.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_423413f5328992', 'les_796775d08a585f', 2, 'practice', 'multiple_choice', 1, 'Which change has ΔS > 0?', '{"choices":["H₂O(g) → H₂O(l)","CO₂(s) → CO₂(g)","N₂(g) + 3H₂(g) → 2NH₃(g)","Ag⁺(aq) + Cl⁻(aq) → AgCl(s)"],"answer":1}', '["Look for more freedom of motion."]', 'Sublimation turns a solid into a gas.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_331e757515bdb4', 'les_796775d08a585f', 3, 'practice', 'multiple_choice', 2, 'For CaCO₃(s) → CaO(s) + CO₂(g), ΔS is…', '{"choices":["positive","negative","zero","impossible to predict"],"answer":0}', '["Count moles of gas."]', '0 → 1 mol gas.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_49a289c3eba6bc', 'les_796775d08a585f', 4, 'practice', 'multiple_choice', 2, 'Which has the highest molar entropy at 298 K?', '{"choices":["CH₄(g)","C₂H₆(g)","C₃H₈(g)","C(diamond)"],"answer":2}', '["Bigger, more complex molecules have more ways to move."]', 'Propane has the most atoms and vibrational modes.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c64fab3a1e016d', 'les_796775d08a585f', 5, 'review', 'multiple_choice', 3, 'Why does a gas expand into a vacuum?', '{"choices":["it releases heat","the expanded state has vastly more microstates","pressure pulls it","its energy increases"],"answer":1}', '[]', 'No energy change; probability drives it.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_796775d08a585f', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_796775d08a585f', (SELECT id FROM formulas WHERE slug = 'free-energy'), 1);

-- Lesson: nernst-equation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_886104b3e84524', 'nernst-equation', 'Cell potential under nonstandard conditions', 'Use the Nernst equation to find cell potential at any concentrations, explain why batteries run down, and analyze concentration cells.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e838351f2e5367', 'les_886104b3e84524', 1, 'Write Q for a cell reaction and apply E = E° − (0.0592/n) log Q at 298 K.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e9df1f21348a9d', 'les_886104b3e84524', 2, 'Predict qualitatively how concentration changes raise or lower E.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5eb927268c64fd', 'les_886104b3e84524', 3, 'Calculate the potential of a concentration cell, where E° = 0.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e838351f2e5367', 'les_886104b3e84524', 'learn', 1, 'definition', '{"term":"The Nernst equation","body":"From $\\Delta G = \\Delta G^\\circ + RT\\ln Q$ and $\\Delta G = -nFE$: $E = E^\\circ - \\frac{RT}{nF}\\ln Q$. At 298 K this is $E = E^\\circ - \\frac{0.0592}{n}\\log Q$. Solids are left out of Q."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9df1f21348a9d', 'les_886104b3e84524', 'learn', 2, 'worked_example', '{"title":"Zn/Cu cell with [Zn²⁺] = 1.0 M, [Cu²⁺] = 0.010 M","steps":[{"latex":"Q = \\tfrac{[\\text{Zn}^{2+}]}{[\\text{Cu}^{2+}]} = 100","explanation":"Zn²⁺ is a product, Cu²⁺ a reactant."},{"latex":"E = 1.10 - \\tfrac{0.0592}{2}\\log 100","explanation":""},{"latex":"= 1.10 - 0.059 = 1.04\\ \\text{V}","explanation":"Less reactant, lower voltage."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5eb927268c64fd', 'les_886104b3e84524', 'experiment', 3, 'activity', '{"activity":"galvanic-cell","title":"Nernst equation","params":{"left":"Zn","right":"Cu","leftConc":1,"rightConc":0.01}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_278cad74874a8d', 'les_886104b3e84524', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Lower the Cu²⁺ concentration step by step. Each factor of 10 drops E by about 0.03 V. As the cell discharges toward equilibrium, Q → K and E → 0: a dead battery."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe137c95f1b9a2', 'les_886104b3e84524', 'learn', 5, 'definition', '{"term":"Concentration cells","body":"Two half-cells of the same metal with different ion concentrations: $E^\\circ = 0$, so the voltage comes entirely from the Nernst term. Electrons flow so as to equalize the concentrations: the dilute side is the anode."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e697d2d3974d7', 'les_886104b3e84524', 'learn', 6, 'worked_example', '{"title":"Cu | Cu²⁺(0.010 M) || Cu²⁺(1.0 M) | Cu","steps":[{"latex":"Q = \\tfrac{0.010}{1.0} = 0.010","explanation":""},{"latex":"E = 0 - \\tfrac{0.0592}{2}\\log 0.010","explanation":""},{"latex":"= +0.0592\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8567c8653ca55', 'les_886104b3e84524', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"pH meters are concentration cells for H⁺; nerve cells keep a resting potential of about −70 mV from ion concentration differences across their membranes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e838351f2e5367', 'les_886104b3e84524', 1, 'practice', 'numeric', 2, 'Find E for the Zn/Cu cell (E° = 1.10 V) with [Zn²⁺] = 0.10 M and [Cu²⁺] = 1.0 M, to two decimal places.', '{"answer":1.13,"tolerance":0.01,"unit":"V"}', '["Q = 0.10."]', '$1.10 - 0.0296\log 0.10 = 1.13$ V.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9df1f21348a9d', 'les_886104b3e84524', 2, 'practice', 'numeric', 3, 'Find E for the Zn/Cu cell with [Zn²⁺] = 0.50 M and [Cu²⁺] = 0.010 M, to two decimal places.', '{"answer":1.05,"tolerance":0.01,"unit":"V"}', '["Q = 50.","n = 2."]', '$1.10 - 0.0296\log 50 = 1.05$ V.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5eb927268c64fd', 'les_886104b3e84524', 3, 'practice', 'numeric', 3, 'A silver concentration cell (n = 1) has 1.0 M Ag⁺ and 1.0 × 10⁻⁵ M Ag⁺. Find E in V, to three decimal places.', '{"answer":0.296,"tolerance":0.002,"unit":"V"}', '["E° = 0; Q = 10⁻⁵."]', '$-0.0592\log(10^{-5}) = 0.296$ V.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_278cad74874a8d', 'les_886104b3e84524', 4, 'practice', 'multiple_choice', 2, 'In a galvanic cell, increasing the concentration of a reactant ion…', '{"choices":["lowers E","raises E","leaves E unchanged","makes E° larger"],"answer":1}', '["Q falls."]', 'Smaller Q, larger E.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fe137c95f1b9a2', 'les_886104b3e84524', 5, 'review', 'multiple_choice', 3, 'When a battery is completely dead…', '{"choices":["E° = 0","Q = K and E = 0","Q = 0","n = 0"],"answer":1}', '[]', 'The reaction has reached equilibrium.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_886104b3e84524', (SELECT id FROM concepts WHERE slug = 'electrochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_886104b3e84524', (SELECT id FROM formulas WHERE slug = 'electrochemistry'), 1);

-- Lesson: ph-and-pka
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cae99d956c5538', 'ph-and-pka', 'pH and pKa', 'Compare pH with pKa to predict which form of an acid dominates, and calculate the fraction ionized at a given pH.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f4cbb62064bc0b', 'les_cae99d956c5538', 1, 'State the rule: pH < pKa favors HA; pH > pKa favors A⁻; pH = pKa gives equal amounts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7bf0f26f7368fd', 'les_cae99d956c5538', 2, 'Convert a pH − pKa difference into a ratio [A⁻]/[HA].');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35b654ba523b2a', 'les_cae99d956c5538', 3, 'Calculate the percent of an acid present in each form.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4cbb62064bc0b', 'les_cae99d956c5538', 'learn', 1, 'definition', '{"term":"The ratio rule","body":"Rearranging $K_a$ gives $\\frac{[\\text{A}^-]}{[\\text{HA}]} = 10^{\\,\\text{pH} - \\text{p}K_a}$. Every unit of pH above the pKa multiplies the ratio by 10. The pH of the solution is set by everything in it; this rule tells you how one acid distributes itself at that pH."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bf0f26f7368fd', 'les_cae99d956c5538', 'learn', 2, 'definition', '{"term":"Fraction ionized","body":"Fraction as A⁻ $= \\frac{R}{1+R}$ where $R = 10^{\\,\\text{pH}-\\text{p}K_a}$. At pH = pKa + 1 that is 10/11 = 91%; at pKa + 2 it is 99%."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35b654ba523b2a', 'les_cae99d956c5538', 'learn', 3, 'worked_example', '{"title":"Acetic acid (pKa 4.74) in a solution at pH 5.74","steps":[{"latex":"R = 10^{5.74-4.74} = 10","explanation":""},{"latex":"\\tfrac{10}{11} = 0.909","explanation":"91% acetate, 9% acetic acid."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e1ae3615a62ac', 'les_cae99d956c5538', 'learn', 4, 'worked_example', '{"title":"The same acid at pH 2.74 (stomach-like)","steps":[{"latex":"R = 10^{-2} = 0.01","explanation":""},{"latex":"\\tfrac{0.01}{1.01} \\approx 1\\%","explanation":"Almost entirely neutral HA."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_74a94ecf725375', 'les_cae99d956c5538', 'learn', 5, 'callout', '{"tone":"tip","title":"Quick table","body":"pH − pKa = −2, −1, 0, +1, +2 gives about 1%, 9%, 50%, 91%, 99% as A⁻. Indicators change color across this ±1 window, which is why their ranges span about 2 pH units."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8da47c322c0848', 'les_cae99d956c5538', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Aspirin (pKa 3.5) is mostly neutral in the stomach and can cross cell membranes there; amino acids switch charge states as pH moves past each pKa, which is how gel electrophoresis separates proteins."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4cbb62064bc0b', 'les_cae99d956c5538', 1, 'practice', 'numeric', 2, 'An acid with pKa 4.0 is in a solution of pH 6.0. Find the ratio [A⁻]/[HA].', '{"answer":100,"tolerance":0.5}', '["10 to the power (pH − pKa)."]', '$10^{2} = 100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7bf0f26f7368fd', 'les_cae99d956c5538', 2, 'practice', 'numeric', 3, 'What percent of acetic acid (pKa 4.74) is ionized at pH 5.74? Give one decimal place.', '{"answer":90.9,"tolerance":0.1,"unit":"%"}', '["R = 10.","Fraction = R/(1 + R)."]', '$10/11 = 90.9\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35b654ba523b2a', 'les_cae99d956c5538', 3, 'practice', 'multiple_choice', 2, 'At pH 9.0, an acid with pKa 7.0 is mostly…', '{"choices":["HA","A⁻","equal amounts","fully neutral"],"answer":1}', '["pH above pKa."]', 'Ratio 100:1 in favor of A⁻.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e1ae3615a62ac', 'les_cae99d956c5538', 4, 'practice', 'multiple_choice', 2, 'At what pH are HA and A⁻ present in equal amounts?', '{"choices":["pH 7","pH = pKa","pH = pKw","pH 0"],"answer":1}', '[]', 'log 1 = 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_74a94ecf725375', 'les_cae99d956c5538', 5, 'review', 'multiple_choice', 3, 'Phenol red has pKa 7.9. Its color changes over roughly…', '{"choices":["pH 3–5","pH 6.9–8.9","pH 10–12","pH 7.9 only"],"answer":1}', '["About pKa ± 1."]', 'The visible change spans pKa ± 1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cae99d956c5538', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cae99d956c5538', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);

-- Lesson: strong-acid-base-ph
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b8566d269ca6bf', 'strong-acid-base-ph', 'pH and pOH of strong acids and bases', 'Calculate pH and pOH for strong acids and bases, including bases that release two hydroxides, very dilute solutions and water at other temperatures.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e83705527f47ec', 'les_b8566d269ca6bf', 1, 'Treat strong acids and bases as 100% ionized and find [H₃O⁺] or [OH⁻] directly.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8776aee400d1af', 'les_b8566d269ca6bf', 2, 'Use pH + pOH = pK_w and account for bases such as Ba(OH)₂ that give 2 OH⁻.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_072a52d8277c35', 'les_b8566d269ca6bf', 3, 'Recognize when water''s own ionization matters and how K_w changes with temperature.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e83705527f47ec', 'les_b8566d269ca6bf', 'learn', 1, 'definition', '{"term":"Strong means complete","body":"The strong acids (HCl, HBr, HI, HNO₃, HClO₄, H₂SO₄ for its first proton) and the group 1 and heavy group 2 hydroxides ionize completely. The ion concentration equals the formula concentration times the number of H⁺ or OH⁻ released: no ICE table needed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8776aee400d1af', 'les_b8566d269ca6bf', 'learn', 2, 'definition', '{"term":"The pH toolkit","body":"$\\text{pH} = -\\log[\\text{H}_3\\text{O}^+]$, $\\text{pOH} = -\\log[\\text{OH}^-]$, and $[\\text{H}_3\\text{O}^+][\\text{OH}^-] = K_w = 1.0\\times10^{-14}$ at 25 °C, so $\\text{pH} + \\text{pOH} = 14.00$. Each pH unit is a factor of 10 in [H₃O⁺]."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_072a52d8277c35', 'les_b8566d269ca6bf', 'learn', 3, 'worked_example', '{"title":"pH of 0.020 M HNO₃","steps":[{"latex":"[\\text{H}_3\\text{O}^+] = 0.020\\ \\text{M}","explanation":"One H⁺ per HNO₃, fully ionized."},{"latex":"\\text{pH} = -\\log 0.020 = 1.70","explanation":"Two significant figures in 0.020 → two decimal places."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3fafc5f65d89e5', 'les_b8566d269ca6bf', 'learn', 4, 'worked_example', '{"title":"pH of 0.0050 M Ba(OH)₂","steps":[{"latex":"[\\text{OH}^-] = 2(0.0050) = 0.010\\ \\text{M}","explanation":"Each Ba(OH)₂ releases two OH⁻."},{"latex":"\\text{pOH} = 2.00","explanation":""},{"latex":"\\text{pH} = 14.00 - 2.00 = 12.00","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6eb87c7ab06626', 'les_b8566d269ca6bf', 'learn', 5, 'worked_example', '{"title":"A very dilute acid: 1.0 × 10⁻⁸ M HCl","steps":[{"latex":"\\text{pH} \\ne 8","explanation":"An acid can''t make water basic."},{"latex":"x(x - 10^{-8}) = 10^{-14}","explanation":"x = [H₃O⁺]; water''s ions now matter."},{"latex":"x = 1.05\\times10^{-7}","explanation":"Quadratic formula."},{"latex":"\\text{pH} = 6.98","explanation":"Just barely acidic."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba470616ce6634', 'les_b8566d269ca6bf', 'learn', 6, 'callout', '{"tone":"note","title":"Neutral isn''t always 7","body":"$K_w$ grows with temperature because water''s ionization is endothermic. At 50 °C, $K_w \\approx 5.5\\times10^{-14}$, so neutral water has $[\\text{H}_3\\text{O}^+] = \\sqrt{K_w}$ and pH 6.63. It is still neutral: [H₃O⁺] = [OH⁻]."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3eb22e2b988a41', 'les_b8566d269ca6bf', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Lab stock solutions, pool chemistry and industrial cleaning all rely on quick strong-acid and strong-base pH estimates; a 10-fold dilution of a strong acid raises its pH by exactly 1."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e83705527f47ec', 'les_b8566d269ca6bf', 1, 'practice', 'numeric', 1, 'Find the pH of 0.0035 M HCl, to two decimal places.', '{"answer":2.46,"tolerance":0.01}', '["HCl is strong: [H₃O⁺] = 0.0035 M."]', '$-\log 0.0035 = 2.46$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8776aee400d1af', 'les_b8566d269ca6bf', 2, 'practice', 'numeric', 2, 'Find the pH of 0.015 M KOH, to two decimal places.', '{"answer":12.18,"tolerance":0.01}', '["Find pOH first."]', 'pOH $= -\log 0.015 = 1.82$; pH $= 14.00 - 1.82 = 12.18$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_072a52d8277c35', 'les_b8566d269ca6bf', 3, 'practice', 'numeric', 3, 'You mix 25.0 mL of 0.100 M HCl with 15.0 mL of 0.100 M NaOH. Find the pH, to two decimal places.', '{"answer":1.6,"tolerance":0.01}', '["Count moles and neutralize first.","Divide the excess by the total volume."]', 'H⁺ 0.00250 mol, OH⁻ 0.00150 mol; excess H⁺ 0.00100 mol in 0.0400 L = 0.0250 M; pH 1.60.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3fafc5f65d89e5', 'les_b8566d269ca6bf', 4, 'practice', 'multiple_choice', 2, 'A 0.010 M solution of which base has pH 12.30?', '{"choices":["NaOH","KOH","Ca(OH)₂","NH₃"],"answer":2}', '["pOH = 1.70 means [OH⁻] = 0.020 M."]', 'Two OH⁻ per formula unit: [OH⁻] = 0.020 M.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6eb87c7ab06626', 'les_b8566d269ca6bf', 5, 'review', 'multiple_choice', 3, 'At 50 °C pure water has pH 6.63. It is…', '{"choices":["acidic","neutral","basic","impossible to classify"],"answer":1}', '["Compare [H₃O⁺] and [OH⁻]."]', 'Neutral means equal concentrations, which still holds; only K_w changed.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b8566d269ca6bf', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b8566d269ca6bf', (SELECT id FROM formulas WHERE slug = 'ph-scale'), 1);

-- Lesson: thermo-kinetic-control
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_425b04e8301c35', 'thermo-kinetic-control', 'Thermodynamic and kinetic control', 'Distinguish whether a reaction can happen (ΔG) from how fast it happens (Ea), and explain why some favorable reactions are not observed.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cb017802ed0e65', 'les_425b04e8301c35', 1, 'Explain that ΔG° predicts favorability but not rate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_677547bd98d2a2', 'les_425b04e8301c35', 2, 'Use activation energy to explain why favorable reactions can be too slow to observe.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_78e0f695275629', 'les_425b04e8301c35', 3, 'Distinguish the kinetic product (formed fastest) from the thermodynamic product (most stable).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb017802ed0e65', 'les_425b04e8301c35', 'learn', 1, 'definition', '{"term":"Two separate questions","body":"Thermodynamics asks whether products are favored: the sign of $\\Delta G^\\circ$. Kinetics asks how fast they form: the height of the activation barrier $E_a$. A reaction with $\\Delta G^\\circ < 0$ but a large $E_a$ is under kinetic control: favorable, yet so slow it doesn''t measurably happen."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_677547bd98d2a2', 'les_425b04e8301c35', 'learn', 2, 'worked_example', '{"title":"Diamond → graphite at 298 K","steps":[{"latex":"\\Delta H^\\circ = -1.9\\ \\text{kJ},\\ \\Delta S^\\circ = +3.3\\ \\text{J/K}","explanation":""},{"latex":"\\Delta G^\\circ = -1.9 - 298(0.0033)","explanation":""},{"latex":"= -2.9\\ \\text{kJ}","explanation":"Favorable."},{"latex":"E_a \\text{ is enormous}","explanation":"Breaking a 3-D covalent network: no change in millions of years."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_78e0f695275629', 'les_425b04e8301c35', 'learn', 3, 'callout', '{"tone":"note","title":"Picture it","body":"On an energy diagram, ΔG° is the drop from reactants to products and Eₐ is the hill in between. A deep drop behind a tall hill is favorable but slow; a catalyst lowers the hill without changing the drop."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b19f3fe9fb6b9', 'les_425b04e8301c35', 'learn', 4, 'definition', '{"term":"Kinetic vs thermodynamic product","body":"When two products are possible, the one with the lower barrier forms faster (kinetic product). The one with the lower free energy is favored at equilibrium (thermodynamic product). Low temperature and short times favor the kinetic product; high temperature and long times let the system reach the thermodynamic one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9de5267b6c117', 'les_425b04e8301c35', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Wood and gasoline are thermodynamically unstable in air but need a spark to get over the barrier. Living cells survive because their molecules are kinetically stable, and enzymes choose which favorable reactions actually run."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb017802ed0e65', 'les_425b04e8301c35', 1, 'practice', 'numeric', 2, 'Find ΔG° for C(diamond) → C(graphite) at 298 K, given ΔH° = −1.9 kJ and ΔS° = +3.3 J/K. One decimal place.', '{"answer":-2.9,"tolerance":0.1,"unit":"kJ"}', '["Convert ΔS° to kJ/K."]', '$-1.9 - 0.98 = -2.9$ kJ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_677547bd98d2a2', 'les_425b04e8301c35', 2, 'practice', 'multiple_choice', 2, 'A mixture of H₂ and O₂ sits unchanged for years even though ΔG° ≪ 0. This is because…', '{"choices":["ΔH > 0","the activation energy is high","K is small","ΔS > 0"],"answer":1}', '[]', 'It is kinetically controlled; a spark starts it.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_78e0f695275629', 'les_425b04e8301c35', 3, 'practice', 'multiple_choice', 2, 'A catalyst changes…', '{"choices":["ΔG°","K","Ea and the rate","which side is favored"],"answer":2}', '[]', 'Only the pathway.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b19f3fe9fb6b9', 'les_425b04e8301c35', 4, 'practice', 'multiple_choice', 3, 'Product A forms faster but product B is more stable. At high temperature for a long time you mostly get…', '{"choices":["A","B","equal amounts","neither"],"answer":1}', '["Given enough energy and time, the system reaches equilibrium."]', 'The thermodynamic product.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9de5267b6c117', 'les_425b04e8301c35', 5, 'review', 'multiple_choice', 3, 'If ΔG° > 0 for a reaction, adding a catalyst…', '{"choices":["makes it favorable","doesn''t make it favorable","reverses ΔH","raises K"],"answer":1}', '[]', 'Catalysts can''t change ΔG°.');
